steps.script:
function transform(ctx) {
  var qs_full = ctx.vars.qs_full || "";
  var idx = qs_full.indexOf("wlanacname");
  if (!qs_full || idx < 0) throw new Error("未能从门户首页提取认证跳转查询串（原实现要求链接含 wlanacname 参数），请核对门户地址");
  var qs = qs_full.substring(idx) + "'"; // NetLogin.cs L139-141：取整个正则匹配值（含结尾单引号）再 Substring(IndexOf("wlanacname"))
  // NetLogin.cs L12-17：serviceStrings 为门户侧预编码字符串，经 FormUrlEncodedContent 再编码一次 => 双重编码
  var MAP = { "校园网": "%e6%a0%a1%e5%9b%ad%e7%bd%91", "移动": "%E4%B8%AD%E5%9B%BD%E7%A7%BB%E5%8A%A8", "联通": "%e4%b8%ad%e5%9b%bd%e8%81%94%e9%80%9a", "电信": "%e4%b8%ad%e5%9b%bd%e7%94%b5%e4%bf%a1" };
  var isp = (ctx.isp || "").trim();
  var service = isp ? (MAP[isp] !== undefined ? MAP[isp] : isp) : MAP["校园网"];
  return { eu: url_encode(ctx.username || ""), ep: url_encode(ctx.password || ""), es: url_encode(service), qse: url_encode(url_encode(qs)) };
}
